// A very basic, non-chained implementation for interviews
class MyPromise {
  constructor(executor) {
    this.state = 'pending';
    this.value = undefined;
    this.onResolveCallbacks = [];

    const resolve = (val) => {
      if (this.state === 'pending') {
        this.state = 'fulfilled';
        this.value = val;
        // Promises run asynchronously, so use setTimeout
        this.onResolveCallbacks.forEach(cb => setTimeout(() => cb(val), 0));
      }
    };

    try {
      executor(resolve);
    } catch (err) {
      // In a real implementation, handle reject here
    }
  }

  then(callback) {
    if (this.state === 'fulfilled') {
      setTimeout(() => callback(this.value), 0);
    } else if (this.state === 'pending') {
      this.onResolveCallbacks.push(callback);
    }
    // Returns a new Promise to allow chaining in a full implementation
    return this;
  }
}

const p = new MyPromise((resolve) => {
  setTimeout(() => resolve("Hello Custom Promise!"), 1000);
});

p.then(res => console.log(res));
